'type": "paragraph", "inlineContent": [{"type": "text", "text": "Dynamic Type is a system-level feature in iOS, iPadOS, tvOS, visionOS, and watchOS that lets people adjust the size of visible text on their device to ensure readability and comfort. For related guidance, see "}, {"identifier": "doc://com.apple.HIG/design/Human-Interface-Guidelines/accessibility", "isActive": true, "type": "reference"}, {"type": "text", "text": "."}]}, {"type": "row", "numberOfColumns": 2, "columns": [{"content": [{"type": "paragraph", "inlineContent": [{"metadata": {"deviceFrame": "iPhone16", "abstract": [{"type": "text", "text": "Mail content at the default text size"}]}, "identifier": "typography-default-type.png", "type": "image"}]}], "size": 1}, {"content": [{"type": "paragraph", "inlineContent": [{"type": "image", "metadata": {"deviceFrame": "iPhone16", "abstract": [{"text": "Mail content at the largest accessibility text size", "type": "text"}]}, "identifier": "typography-dynamic-type.png"}]}], "size": 1}]}, {"type": "paragraph", "inlineContent": [{"type": "text", "text": "For a list of available Dynamic Type sizes, see "}, {"type": "reference", "identifier": "doc://com.apple.HIG/design/Human-Interface-Guidelines/typography#Specifications", "isActive": true}, {"text": ". You can also download Dynamic Type size tables in the ", "type": "text"}, {"identifier": "https://developer.apple.com/design/resources/", "isActive": true, "type": "reference"}, {"text": " for each platform.", "type": "text"}]}, {"inlineContent": [{"text": "For developer guidance, see ", "type": "text"}, {"identifier": "doc://com.apple.documentation/documentation/SwiftUI/Text-input-and-output", "isActive": true, "type": "reference"}, {"type": "text", "text": ". To support Dynamic Type in Unity-based games, use "}, {"type": "reference", "overridingTitleInlineContent": [{"type": "text", "text": "Apple\\u2019s Unity plug-ins"}], "overridingTitle": "Apple\\u2019s Unity plug-ins", "isActive": true, "identifier": "https://github.com/apple/unityplugins"}, {"type": "text", "text": "."}], "type": "paragraph"}, {"inlineContent": [{"type": "strong", "inlineContent": [{"text": "Make sure your app\\u2019s layout adapts to all font sizes.", "type": "text"}]}, {"type": "text", "text": " Verify that your design scales, and that text and glyphs are legible at all font sizes. On iPhone or iPad, turn on Larger Accessibility Text Sizes in Settings > Accessibility > Display & Text Size > Larger Text, and confirm that your app remains comfortably readable."}], "type": "paragraph"}, {"inlineContent": [{"inlineContent": [{"text": "Increase the size of meaningful interface icons as font size increases.", "type": "text"}], "type": "strong"}, {"type": "text", "text": " If you use interface icons to communicate important information, make sure they\\u2019re easy to view at larger font sizes too. When you use "}, {"type": "reference", "isActive": true, "identifier": "doc://com.apple.HIG/design/Human-Interface-Guidelines/sf-symbols"}, {"type": "text", "text": ", you get icons that scale automatically with Dynamic Type size changes."}], "type": "paragraph"}, {"type": "paragraph", "inlineContent": [{"inlineContent": [{"text": "Keep text truncation to a minimum as font size increases.", "type": "text"}], "type": "strong"}, '
